CREATE SCHEMA content;
REVOKE ALL ON SCHEMA content FROM PUBLIC;
CREATE TABLE content.migration_history(id text PRIMARY KEY, checksum text NOT NULL);
CREATE TABLE content.instance(id integer PRIMARY KEY CHECK(id=1),workspace_id text NOT NULL);
CREATE TABLE content.input_items(stage_id text NOT NULL,kind text NOT NULL,item_key text NOT NULL,ordinal integer NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(stage_id,kind,item_key),UNIQUE(stage_id,kind,ordinal));
CREATE TABLE content.input_manifests(stage_id text PRIMARY KEY,source_id text NOT NULL,digest text NOT NULL,header jsonb NOT NULL,counts jsonb NOT NULL);
CREATE TABLE content.sources(id text PRIMARY KEY,source_key text UNIQUE NOT NULL,requested_revision integer NOT NULL DEFAULT 0,last_complete_revision integer NOT NULL DEFAULT 0,last_complete_generation integer NOT NULL DEFAULT 0,publication_id text NOT NULL);
CREATE TABLE content.source_revisions(source_id text NOT NULL REFERENCES content.sources(id),revision integer NOT NULL,stage_id text NOT NULL REFERENCES content.input_manifests(stage_id),digest text NOT NULL,PRIMARY KEY(source_id,revision));
CREATE TABLE content.tasks(source_id text NOT NULL,generation integer NOT NULL,revision integer NOT NULL,phase text NOT NULL DEFAULT 'routes',cursor integer NOT NULL DEFAULT 0,exercise_state jsonb,state text NOT NULL DEFAULT 'pending',lease_token text,lease_until timestamptz,error jsonb,built_at text,PRIMARY KEY(source_id,generation),FOREIGN KEY(source_id,revision) REFERENCES content.source_revisions(source_id,revision));
CREATE TABLE content.artifacts(id text PRIMARY KEY,starting_fen text NOT NULL,moves jsonb NOT NULL,learner_color text NOT NULL,version text NOT NULL,cursor integer NOT NULL DEFAULT 0,next_fen text NOT NULL,complete boolean NOT NULL DEFAULT false,epoch bigint NOT NULL DEFAULT 1);
CREATE TABLE content.generation_routes(source_id text NOT NULL,generation integer NOT NULL,route_key text NOT NULL,policy_key text NOT NULL,repertoire_key text NOT NULL,artifact_id text NOT NULL REFERENCES content.artifacts(id),PRIMARY KEY(source_id,generation,route_key,policy_key),FOREIGN KEY(source_id,generation) REFERENCES content.tasks(source_id,generation));
CREATE INDEX generation_routes_artifact ON content.generation_routes(artifact_id);
CREATE TABLE content.positions(position_key text PRIMARY KEY,fen text NOT NULL,side_to_move text NOT NULL,legal_version text,reply_count integer,fingerprint text);
CREATE TABLE content.legal_replies(position_key text NOT NULL REFERENCES content.positions(position_key),move_uci text NOT NULL,resulting_position_key text NOT NULL REFERENCES content.positions(position_key),PRIMARY KEY(position_key,move_uci));
CREATE TABLE content.occurrences(artifact_id text NOT NULL REFERENCES content.artifacts(id),ply integer NOT NULL,fen text NOT NULL,position_key text NOT NULL REFERENCES content.positions(position_key),opponent boolean NOT NULL,authored_move text,PRIMARY KEY(artifact_id,ply));
CREATE TABLE content.exercise_identities(source_id text NOT NULL,exercise_key text NOT NULL,card_id text NOT NULL,policy_key text NOT NULL,decision_key text NOT NULL,kind text NOT NULL,supersedes_key text,PRIMARY KEY(source_id,exercise_key),UNIQUE(card_id));
CREATE TABLE content.exercise_versions(source_id text NOT NULL,exercise_key text NOT NULL,revision integer NOT NULL,digest text NOT NULL,PRIMARY KEY(source_id,exercise_key,revision),FOREIGN KEY(source_id,exercise_key) REFERENCES content.exercise_identities(source_id,exercise_key));
CREATE TABLE content.generation_exercises(source_id text NOT NULL,generation integer NOT NULL,exercise_key text NOT NULL,exercise_revision integer NOT NULL,PRIMARY KEY(source_id,generation,exercise_key),FOREIGN KEY(source_id,generation) REFERENCES content.tasks(source_id,generation));
CREATE TABLE content.responses(source_id text NOT NULL,generation integer NOT NULL,route_key text NOT NULL,policy_key text NOT NULL,ply integer NOT NULL,exercise_key text NOT NULL,position_key text NOT NULL,accepted_moves jsonb NOT NULL,PRIMARY KEY(source_id,generation,route_key,policy_key,ply));
CREATE TABLE content.publications(publication_id text NOT NULL,generation integer NOT NULL,source_id text NOT NULL,source_revision integer NOT NULL,payload text NOT NULL,digest text NOT NULL,provenance jsonb NOT NULL,PRIMARY KEY(publication_id,generation));
CREATE TABLE content.collector(id integer PRIMARY KEY CHECK(id=1),pending boolean NOT NULL DEFAULT false,deliveries bigint NOT NULL DEFAULT 0);
INSERT INTO content.collector(id) VALUES(1);
